import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"自带密钥","description":"","frontmatter":{},"headers":[],"relativePath":"zh/online/byok.md","filePath":"zh/online/byok.md","lastUpdated":1792570296000}'),n={name:"zh/online/byok.md"};function l(s,a,i,h,d,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="自带密钥" tabindex="-1">自带密钥 <a class="header-anchor" href="#自带密钥" aria-label="Permalink to &quot;自带密钥&quot;">​</a></h1><p>用自己的模型和数据源密钥运行任务，替代 PaperSeek 服务。使用自带密钥的任务不消耗积分；上游费用和速率限制由你自己的服务商账户承担。</p><h2 id="配置密钥" tabindex="-1">配置密钥 <a class="header-anchor" href="#配置密钥" aria-label="Permalink to &quot;配置密钥&quot;">​</a></h2><ol><li>在侧栏底部的账户菜单中选择 <strong>自带密钥</strong>。</li><li>在 <strong>设置 › 模型服务</strong> 中点击<strong>添加连接</strong>，填写模型信息和密钥，然后点击<strong>保存</strong>（参见<a href="./../guide/models">模型与排序</a>）。</li><li>在 <strong>设置 › 数据源</strong> 中，点击来源对应的<strong>配置</strong>（或<strong>配置密钥</strong>），保存密钥。自带密钥模式下，所有支持密钥的数据源都必须提供密钥，包括 OpenAlex、PubMed 和 Semantic Scholar；arXiv、Crossref 和 PaperHub 无需密钥。</li></ol><p>模型密钥与数据源密钥是两套凭据。模型 API 密钥不能代替文献数据库的访问凭据。</p><h2 id="仅限公网接口" tabindex="-1">仅限公网接口 <a class="header-anchor" href="#仅限公网接口" aria-label="Permalink to &quot;仅限公网接口&quot;">​</a></h2><p>在线版只接受公网模型接口。localhost、<code>127.0.0.1</code>、内网地址等非公开目标会被拦截。要使用自己电脑或网络中的模型，请运行<a href="./../self-hosting/">社区版</a>。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="./privacy">数据与隐私</a> — 已保存密钥如何存储、谁能看到。</li><li><a href="./credits">服务与积分</a> — 另一种选择：使用 PaperSeek 提供的模型。</li></ul>',9)])])}const f=e(n,[["render",l]]);export{_ as __pageData,f as default};
